globalThis.SABA_REFLECTIVE = {"version":2,"sessions":[{"id":1,"title":"از واکنش روزمره تا رهبری بازتابی","subtitle":"پیش از پاسخ، نقش خود را روشن کنیم","coverage":"فصل‌های ۱ تا ۵ · ص ۱–۴۳","output":"شرح یک موقعیت و تشخیص تفاوت تصمیم درباره کار با تصمیم درباره نقش مدیر","sections":[{"id":"daily","title":"یک درخواست ساده، چهار امکان","lead":"همکار می‌پرسد: «این برنامه مورد تأیید شماست؟» پاسخ شما فقط درباره برنامه نیست؛ رابطه و مسئول تصمیم را هم شکل می‌دهد.","blocks":[{"title":"Case فرضی در صبا نفت","text":"کارشناس پروژه پیش‌نویس شیوه گزارش پیشرفت را آماده کرده است. از مدیر می‌خواهد آن را تأیید کند. هنوز مسئله‌ای فوری یا تصمیم خارج از اختیار مطرح نیست. آیا مدیر باید متن را اصلاح و تصویب کند، با تیم تصمیم بگیرد، از تهیه‌کننده استدلال بخواهد یا امکان ارزیابی مستقل را فراهم کند؟"},{"title":"پرسش مقدم بر راه‌حل","text":"پیش از اینکه درباره درستی متن نظر بدهید، مشخص کنید چه کسی باید آن را ارزیابی کند و چرا. عنوان شغلی شما به‌تنهایی پاسخ این پرسش نیست. همچنین، سکوت و بی‌پاسخ‌گذاشتن هم پیام رابطه‌ای دارد."}],"source":{"chapter":"۱","pages":"۱–۳"},"prompt":"اولین واکنش شما چه بود؟ این واکنش چه مسئولیتی را برای شما و همکار تعریف می‌کند؟","english":"What role am I taking on here?"},{"id":"assumptions","title":"فرض‌های پشت توصیه‌های رهبری","lead":"یک توصیه آشنا را از حالت شعار خارج کنیم و شرایط کاربردش را ببینیم.","blocks":[{"title":"از توصیه به پرسش","text":"عبارت‌هایی مثل «همیشه اختیار بده» یا «رهبر باید پاسخ داشته باشد» بدون مشخص‌کردن بافت، کافی نیستند. در محیط کار گاهی روش و معیار از پیش روشن است و گاهی حتی نتیجه دقیق معلوم نیست. پرسش مفید این است: این توصیه، تحت چه شرایطی و برای چه رابطه‌ای کار می‌کند؟"},{"title":"چالش‌هایی که مدیر هر روز می‌بیند","text":"حل مسئله، تصمیم، تقسیم کار، روشن‌کردن نتیجه و فرایند، همکاری، انگیزش، رشد، ایده‌پردازی و بازبینی عمل، ده موقعیت عملی کتاب‌اند. این فهرست یک طبقه‌بندی روان‌سنجی نیست. در این دوره از آن برای یافتن موقعیت‌های واقعی استفاده می‌کنیم."}],"source":{"chapter":"۲ و ۳","pages":"۵–۲۵"},"prompt":"یک توصیه مدیریتی که زیاد به کار می‌برید بنویسید. چه فرضی درباره توان افراد، ماهیت کار یا اختیار شما پشت آن است؟","english":"Can I challenge that assumption?"},{"id":"reflection","title":"مکث آگاهانه و اعتماد","lead":"بازتابی‌بودن به معنای کندکردن همه تصمیم‌ها نیست؛ یعنی بتوانید نقش و رفتار خود را توضیح دهید.","blocks":[{"title":"شهود و تجربه","text":"واکنش شهودی همیشه اشتباه نیست؛ تجربه می‌تواند به تشخیص سریع کمک کند. مسئله وقتی پیش می‌آید که عادت یا فشار، بی‌آنکه بررسی کنیم، نقش ما را تعیین کند. در چنین وضعی ممکن است به‌جای نقش متناسب، نقش آشنای قبلی را تکرار کنیم."},{"title":"اعتماد و پیش‌بینی‌پذیری","text":"همکار باید بتواند تا حد معقول بداند در یک نوع موقعیت از شما چه رفتاری خواهد دید. تغییر نقش با توضیح و دلیل، با تغییر رفتار بر اساس خلق‌وخو فرق دارد. روشن‌بودن نقش، بار مذاکره‌های تکراری درباره مسئولیت را کم می‌کند."}],"source":{"chapter":"۴","pages":"۲۷–۳۵"},"prompt":"در یک موقعیت اخیر، چه مقدار از واکنش شما حاصل بررسی و چه مقدار حاصل عادت بود؟ چه توضیحی می‌توانست رفتار شما را برای تیم روشن‌تر کند؟","english":"Let me pause and make sense of the situation."},{"id":"model","title":"نقشه مسیر کتاب","lead":"از شناخت بافت شروع می‌کنیم و با بازاندیشیِ مداوم به همان بافت برمی‌گردیم.","blocks":[{"title":"زنجیره اصلی","text":"بافت رهبری، مبنای تعریف برداشت شما از رهبری و ترکیب نقش‌هاست. این برداشت باید در رابطه با کارکنان روشن شود؛ ابزارهای سازگار به اجرای آن کمک می‌کنند. بازاندیشی، یک مرحله پایانی نیست و همه این مسیر را همراهی می‌کند."},{"title":"مسئولیت مدیر","text":"مدیر در همه چهار نقش، مسئول نتیجه تیم می‌ماند. آنچه تفاوت می‌کند، نحوه تصمیم‌گیری، حل مسئله و توزیع مسئولیت است. مسئولیت تعریف نقش را نمی‌توان به یک تست، مدرس یا واحد منابع انسانی واگذار کرد."}],"source":{"chapter":"۵","pages":"۳۷–۴۳"},"visual":"model","prompt":"در مسئله فعلی شما، ابهام اصلی کجاست: بافت، نقش خودتان، انتظار تیم یا ابزارهایی که استفاده می‌کنید؟","english":"What matters most here?"},{"id":"output","title":"خروجی جلسه و مرور فهم","lead":"یک موقعیت واقعی را برای ادامه دوره انتخاب کنید؛ به‌جای نام اشخاص، درباره نقش و رفتار بنویسید.","blocks":[{"title":"برگه کار","text":"عنوان موقعیت، آنچه رخ داده و چالش رهبری را جدا بنویسید. نمونه: «درخواست تأیید مکرر گزارش»؛ چالش می‌تواند روشن‌نبودن مسئول ارزیابی باشد، نه صرفاً ایراد متن گزارش."},{"title":"آزمایش بین دو جلسه","text":"در یک درخواست مشابه، پیش از پاسخ از خود بپرسید: اکنون چه نقشی از من انتظار می‌رود؟ آیا این همان نقشی است که مناسب می‌دانم؟ فعلاً مشاهده کنید؛ لازم نیست همه رفتارهای خود را یک‌باره تغییر دهید."}],"source":{"chapter":"۱، ۲ و ۹","pages":"۱–۳، ۱۱–۱۲، ۱۱۶–۱۱۸"},"tool":"journal","english":"What stood out to me was…"}],"checks":[{"question":"کدام تعبیر به منطق کتاب نزدیک‌تر است؟","options":["یک رفتار واحد برای همه مدیران بهترین است.","مدیر باید برداشت روشن و متناسبی از رهبری داشته باشد و آن را در رابطه با تیم محقق کند.","تشخیص یک تیپ شخصیتی برای تعیین نقش کافی است."],"correct":1,"why":"کتاب بر بافت، تعریف نقش، رابطه و بازاندیشی تأکید دارد، نه نسخه یکسان."},{"question":"درخواست «این کار مورد تأیید شماست؟» چه چیزی را می‌تواند آشکار کند؟","options":["فقط کیفیت فنی کار را.","اثبات می‌کند همکار توان تصمیم ندارد.","انتظاری درباره نقش مدیر و مسئول ارزیابی یا تصمیم."],"correct":2,"why":"یک درخواست ساده می‌تواند مدیر را به نقشی دعوت کند؛ این دعوت باید دیده و بررسی شود."}]},{"id":2,"title":"بافت رهبری؛ کار و کارکنان","subtitle":"چه شرایطی را واقعاً رهبری می‌کنم؟","coverage":"فصل ۶، بخش‌های ۱ تا ۳ · ص ۴۵–۵۳؛ پیوست ۱۴۹–۱۵۰","output":"نقشه امروز و آیندهِ کار و کارکنان در یک حوزه مشخص","sections":[{"id":"scope","title":"اول حوزه را مشخص کنیم","lead":"برای همه شرکت یک میانگین نسازید؛ ممکن است یک مدیر در چند بافت متفاوت فعالیت کند.","blocks":[{"title":"نمونه در صبا نفت","text":"هماهنگی یک فرایند تکراری ستاد با پیشبرد یک مسئله مبهم در پروژه، بافت یکسانی ندارد. حتی در یک پروژه، تیم گزارش‌گیری و تیم بررسی گزینه‌های توسعه ممکن است به برداشت‌های متفاوتی از رهبری نیاز داشته باشند."},{"title":"واحد تحلیل","text":"نام تیم یا حوزه‌ای را انتخاب کنید که اکنون درباره آن فکر می‌کنید. ارزیابی خود را با یک شاهد از کار همان حوزه پشتیبانی کنید. برای ستون آینده، افق روشنی مانند پایان مرحله فعلی پروژه یا سه ماه بعد تعریف کنید."}],"source":{"chapter":"۶","pages":"۴۵–۴۸، ۶۵–۶۶"},"prompt":"کدام حوزه را بررسی می‌کنید و چه چیزی آن را از حوزه دیگر مسئولیت شما متمایز می‌کند؟","english":"Let’s clarify the context first."},{"id":"tasks","title":"ماهیت کار و فشار ساختاری","lead":"ابهام کار، سطح مسئولیت و فشار زمان را از هم تفکیک کنید.","blocks":[{"title":"قطعیت نتیجه و مسیر","text":"آیا نتیجه مطلوب و روش رسیدن به آن از پیش معلوم‌اند؟ کار تکراریِ دارای استاندارد با پروژه‌ای که نتیجه و مسیرش در حال کشف است فرق دارد. بزرگ‌بودن یک پروژه به‌تنهایی به معنی نامعلوم‌بودن همه کارهای آن نیست."},{"title":"مسئولیت و زمان","text":"مسئولیت عملیاتیِ روزمره با تصمیم‌های راهبردی درباره آینده و چارچوب سازمان فرق دارد. فشار ساختاری زمان هم با یک روز شلوغ یکی نیست: آیا سرعت تصمیم‌گیری به‌طور پایدار برای کار شما حیاتی است؟"}],"source":{"chapter":"۶ و پیوست","pages":"۴۸–۵۰، ۱۴۹"},"prompt":"برای یک کار مشخص، قطعیت نتیجه و قطعیت روش را جدا توضیح دهید. چه چیزی را می‌دانید و چه چیزی هنوز باید روشن شود؟","english":"What is clear, and what remains uncertain?"},{"id":"people","title":"کارکنان؛ برداشت، تفاوت و تخصص","lead":"فرض خود درباره افراد را با واقعیت مشاهده‌شده یکی نگیرید.","blocks":[{"title":"انگیزش و جایگزین‌پذیری","text":"قضاوت مدیر درباره انگیزه، برداشت او از رفتار است؛ دسترسی مستقیمی به انگیزه درونی دیگران ندارد. همچنین، امکان جایگزینی فرد و گزینه‌های حرفه‌ای او به وابستگی متقابل و نگهداشت مربوط‌اند؛ ارزش انسانی فرد را تعیین نمی‌کنند."},{"title":"فردیت و برتری تخصصی","text":"آیا تفاوت دیدگاه و تجربه پذیرفته می‌شود یا همه باید مشابه باشند؟ آیا مدیر از نظر تخصصی برتر است یا کارشناسان هرکدام در حوزه خود بیشتر می‌دانند؟ داشتن دید کلی با دانستن پاسخ همه مسائل تخصصی یکی نیست."}],"source":{"chapter":"۶ و پیوست","pages":"۵۰–۵۳، ۱۵۰"},"prompt":"کدام فرض شما درباره انگیزه یا توان همکاران نیاز به شاهد بیشتر دارد؟ تخصص چه کسی باید در تصمیم بعدی وارد شود؟","english":"What evidence am I drawing on?"},{"id":"map","title":"نقشه بافت؛ امروز و آینده","lead":"این ابزار، توصیف و بازاندیشی شما را ثبت می‌کند؛ از اعداد آن، نقش مطلوب محاسبه نمی‌شود.","blocks":[{"title":"شیوه استفاده","text":"دو گروه «کار» و «کارکنان» را تکمیل کنید. هر عدد، جایگاه تقریبی میان دو توصیف است؛ عدد بالا یا پایین نمره خوب و بد نیست. اگر قضاوتی ندارید، پاسخ را خالی بگذارید."},{"title":"از ثبت تا گفت‌وگو","text":"یک بعد برجسته و یک بعد نامطمئن انتخاب کنید. شواهد و برداشت خود را با یک همتای مطلع مرور کنید. اگر نگاهتان تغییر کرد، نقشه را اصلاح کنید؛ ارزش تمرین در همین بازاندیشی است."}],"source":{"chapter":"۶ و پیوست","pages":"۶۱–۶۶، ۱۴۹–۱۵۰"},"tool":"context","groups":["task","people"],"english":"What might I be overlooking?"},{"id":"output","title":"خروجی جلسه و آزمون برداشت","lead":"دو تفاوت بافتی را انتخاب کنید که واقعاً بر مسئولیت و رفتار شما اثر می‌گذارند.","blocks":[{"title":"خروجی قابل‌مرور","text":"برای هر تفاوت، یک شاهد و یک پرسش درباره نقش خودتان بنویسید. مثال: «کارشناسان از من متخصص‌ترند؛ پس چگونه درباره نتیجه مطالبه‌گری کنم بی‌آنکه روش تخصصی نامطمئن تجویز کنم؟»"},{"title":"پیش از جلسه بعد","text":"یک مشاهده تازه درباره همکاری تیم جمع کنید. هنوز با یک عدد یا یک بعد، نتیجه نگیرید که حتماً باید Coach یا Boss باشید؛ ترکیب شرایط و مسئولیت‌های واقعی را در نظر بگیرید."}],"source":{"chapter":"۶ و ۸","pages":"۶۲–۶۶، ۹۲–۹۴"},"prompt":"کدام بخش نقشه را پس از گفت‌وگو با یک همتا تغییر می‌دهید و چرا؟","english":"I can build on this observation by…"}],"checks":[{"question":"در نقشه بافت، عدد ۱۰ چه معنایی دارد؟","options":["جایگاه نزدیک‌تر به یکی از دو توصیف، بدون معنای بهتر یا بدتر.","رهبری بهتر و حرفه‌ای‌تر.","ضرورت انتخاب نقش Coach."],"correct":0,"why":"مقیاس، توصیفی و برای بازاندیشی است؛ نمره کیفیت رهبری یا فرمول انتخاب نقش نیست."},{"question":"برای ارزیابی آینده چه چیزی باید روشن باشد؟","options":["یکسان‌بودن نمره همه مدیران.","افق زمانی یا مرحله کاری موردنظر.","نظر مدرس درباره شخصیت مدیر."],"correct":1,"why":"کتاب تأکید می‌کند منظور از آینده در همان موقعیت تمرین مشخص شود."}]},{"id":3,"title":"بافت رهبری؛ تیم و سازمان","subtitle":"وابستگی‌ها، اختیار و ریسک را ببینیم","coverage":"فصل ۶، بخش‌های ۴ تا ۷ · ص ۵۴–۶۶؛ پیوست ۱۵۰–۱۵۱","output":"نقشه وابستگی‌ها و حدود اختیار برای همان حوزه منتخب","sections":[{"id":"team","title":"گروه افراد یا تیم وابسته؟","lead":"همه کسانی که زیر یک عنوان سازمانی هستند، الزاماً یک تیم به معنای وابستگی در کار نیستند.","blocks":[{"title":"وابستگی و فاصله","text":"اگر خروجی یک نفر ورودی فرد دیگر است، موفقیت به کیفیت ارتباط میان کارها وابسته می‌شود. در ستاد و کارگاه‌های پراکنده، فاصله مکانی هم باید در شیوه هماهنگی دیده شود؛ حضور در پیام‌رسان جای همه تعامل‌های حضوری را نمی‌گیرد."},{"title":"تعداد افراد و نفوذ","text":"وسعت نظارت بر زمان و توجه مدیر اثر می‌گذارد؛ کتاب یک عدد جادویی برای همه تیم‌ها تجویز نمی‌کند. همچنین، نفوذ ناشی از اختیار رسمی با هماهنگی از طریق تخصص و همکاری فرق دارد؛ به‌ویژه در ارتباط پروژه با پیمانکاران."}],"source":{"chapter":"۶ و پیوست","pages":"۵۴–۵۶، ۱۵۰"},"prompt":"برای یک تحویل بین دو واحد یا دو گروه کاری، وابستگی و اختیار تصمیم چه کسانی را باید روشن کنید؟","english":"Who depends on whom?","photo":{"file":"sabanaft-niayesh.webp","alt":"تصویر واقعی پروژه نیایش صبا نفت","caption":"پروژه نیایش؛ تصویر واقعی از وب‌سایت رسمی صبا نفت. مثال‌های آموزشی این بخش فرضی‌اند."}},{"id":"dynamics","title":"انسجام، تردید سازنده و تعهد","lead":"هماهنگی خوب با هم‌نظرشدن همیشگی یکی نیست.","blocks":[{"title":"اعتماد و اختلاف‌نظر","text":"انسجام به همکاری کمک می‌کند اما ممکن است نقد را هم کم‌رنگ کند. پرسشگری سازنده را فوراً بی‌اعتمادی ننامید. در مسئله پیچیده، شنیدن دیدگاه مخالف می‌تواند بخشی از کارکرد سالم تیم باشد."},{"title":"جهت تعهد و نوع کار","text":"آیا افراد بیشتر در پی رضایت مدیرند یا خود را به مشتری و همکار متعهد می‌دانند؟ در بعضی کارها بهترین پیشنهاد یک نفر نتیجه تیم را جلو می‌برد؛ در بعضی دیگر، ضعف یک حلقه نتیجه کل را محدود می‌کند. این دو حالت، توجه مدیریتی یکسانی نمی‌خواهند."}],"source":{"chapter":"۶ و پیوست","pages":"۵۶–۵۸، ۱۵۱"},"prompt":"در یک تصمیم اخیر، چه کسی نظر متفاوت داشت؟ آن نظر چگونه وارد بررسی شد؟ موفقیت کار بیشتر به ایده ممتاز وابسته بود یا سلامت همه حلقه‌ها؟","english":"Can we broaden the perspective?"},{"id":"organization","title":"جایگاه تیم، ریسک و استقلال","lead":"اثر بر رقابت‌پذیری را از خطر خسارت تفکیک کنید و حدود واقعی اختیار را بشناسید.","blocks":[{"title":"ارزش‌آفرینی و پیشگیری از خسارت","text":"یک حوزه ممکن است با عملکرد ممتاز مزیت ایجاد کند؛ حوزه‌ای دیگر ممکن است با یک خطای جدی خسارت بزرگی بسازد. در صبا نفت، این پرسش‌ها باید برای فعالیت مشخص بررسی شوند؛ نمی‌توان صرفاً از نام واحد، نقش مدیر یا میزان مجاز تجربه‌کردن را نتیجه گرفت."},{"title":"اتصال و اختیار","text":"همکاری بین واحدها، قواعد سازمانی و حدود تفویض، دامنه عمل تیم را شکل می‌دهند. نقش Partner یا Enabler مجوز عبور از تأییدهای لازم یا تصمیم‌های خارج از اختیار نیست. گفت‌وگو درباره نقش باید این مرزها را هم روشن کند."}],"source":{"chapter":"۶ و پیوست","pages":"۵۸–۶۱، ۱۵۱"},"prompt":"کدام تصمیم در اختیار تیم است، کدام نیازمند هماهنگی است و کدام تأیید مشخص می‌خواهد؟","english":"What is within our authority?"},{"id":"map","title":"تکمیل نقشه تیم و سازمان","lead":"نقشه جلسه قبل را با دو گروه «تیم» و «سازمان» کامل کنید.","blocks":[{"title":"تفسیر ترکیبی","text":"بعدها را کنار هم بخوانید. تخصص بالا، وابستگی زیاد و اختیار محدود، هرکدام پیام متفاوتی دارند. نقش را از جمع نمره‌ها به دست نیاورید؛ باید درباره سازگاری آن استدلال کنید."},{"title":"چند بافت، چند برداشت","text":"اگر ستاد، یک پروژه و همکاری با پیمانکاران شرایط متفاوتی دارند، برای هرکدام نقشه جدا بسازید. مقایسه این نقشه‌ها برای فهم تفاوت مسئولیت‌های خودتان است، نه رتبه‌بندی واحدها."}],"source":{"chapter":"۶ و پیوست","pages":"۶۱–۶۶، ۱۵۰–۱۵۱"},"tool":"context","groups":["team","organization"],"english":"The same approach may work differently in another context."},{"id":"output","title":"جمع‌بندی بافت و پیامدها","lead":"سه شرط برجسته را به سه پرسش روشن درباره رهبری تبدیل کنید.","blocks":[{"title":"تمرین همتا","text":"نقشه را برای یک همکار توضیح دهید. از او بخواهید یک فرض را به چالش بکشد و یک شرط جاافتاده را مطرح کند. اختلاف برداشت را در یادداشت خود ثبت کنید."},{"title":"خروجی برای جلسه نقش‌ها","text":"یک تصمیم، یک مسئله و یک ایده از حوزه منتخب آماده کنید. در جلسه بعد برای هرکدام رفتار چهار نقش را مقایسه خواهیم کرد؛ بدون فرض اینکه یک نقش همیشه بهتر است."}],"source":{"chapter":"۶ و ۷","pages":"۶۴–۶۶، ۶۹–۷۰"},"prompt":"کدام سه ویژگی بافت شما مهم‌ترند؟ هرکدام چه سؤالی درباره مسئولیت مدیر ایجاد می‌کنند؟","english":"What are you taking away from this?"}],"checks":[{"question":"تردید سازنده اعضای تیم را چگونه می‌توان فهمید؟","options":["همیشه نشانه بی‌اعتمادی است.","همیشه باید به موافقت تبدیل شود.","ممکن است نشانه استقلال فکر و بررسی جدی تصمیم باشد."],"correct":2,"why":"کتاب میان اعتماد و اطاعت بی‌چون‌وچرا برابری نمی‌گذارد."},{"question":"چرا نقشه حوزه‌های مختلف را جدا نگه می‌داریم؟","options":["چون ممکن است یک مدیر در چند بافت متفاوت نقش‌های اصلی متفاوتی داشته باشد.","برای انتخاب بهترین واحد شرکت.","تا امتیاز بالاتر به مدیر بالادست گزارش شود."],"correct":0,"why":"هدف شناخت تفاوت بافت‌ها و تأمل درباره نقش متناسب است."}]},{"id":4,"title":"چهار نقش، چهار منطق رفتار","subtitle":"Boss · Coach · Partner · Enabler","coverage":"فصل ۷ · ص ۶۹–۸۳؛ پیوست ۱۵۲–۱۵۳","output":"تمایز روشن نقش‌ها و تشخیص رفتارهای آسیب‌زای مشابه آن‌ها","sections":[{"id":"roles","title":"شناخت چهار نقش","lead":"نقش را از محل تصمیم و نحوه توزیع مسئولیت بشناسید؛ صرفاً از لحن جمله نتیجه نگیرید.","blocks":[{"title":"تفاوت بنیادی","text":"در Boss مدیر تصمیم و جهت را روشن می‌کند؛ در Coach فرد را به فکر و تصمیم مسئولانه دعوت می‌کند؛ در Partner تصمیم و حل مسئله مشترک است؛ در Enabler مدیر روی قابلیت و شرایط موفقیت سرمایه‌گذاری می‌کند."},{"title":"همه نقش‌ها می‌توانند مطالبه داشته باشند","text":"Coach هم می‌تواند از تیم راه‌حل جدی بخواهد. Enabler هم می‌تواند به درخواست نامتناسب پاسخ منفی بدهد. احترام یا صراحت به‌تنهایی یک نقش را تعیین نمی‌کند."}],"source":{"chapter":"۷ و پیوست","pages":"۷۰–۷۹، ۱۵۲–۱۵۳"},"tool":"roles","english":"Where does the responsibility for this decision sit?"},{"id":"compare","title":"یک مسئله را چهار جور پیش ببریم","lead":"دو پاسخِ معقول ممکن است بر دو برداشت متفاوت از نقش مدیر تکیه کنند.","blocks":[{"title":"Case فرضی","text":"در یک پروژه، همکار می‌گوید حجم کارش از توافق اولیه بیشتر شده است. Boss می‌تواند پس از بررسی، بازتوزیع کار را تصمیم بگیرد؛ Coach از فرد تحلیل و پیشنهاد بخواهد؛ Partner موضوع را با افراد مرتبط مشترکاً حل کند؛ Enabler شرایطی بسازد که اضافه‌بار تکرار نشود."},{"title":"تمرین مشاهده","text":"یک نفر مدیر و یک نفر همکار باشد. هر بار یک نقش را اجرا کنید. مشاهده‌گر فقط مشخص کند چه کسی مسئله را تحلیل کرد، چه کسی تصمیم گرفت و چه کسی شرایط را فراهم کرد؛ فعلاً مناسب‌بودن نقش را جدا از تشخیص آن بررسی کنید."}],"source":{"chapter":"۷","pages":"۶۹–۸۰"},"prompt":"کدام دو پاسخ، هر دو قابل‌دفاع‌اند؟ برای مقایسه مناسبتشان چه اطلاعات بافتی بیشتری نیاز دارید؟","english":"Would it be helpful to explore another option?"},{"id":"toxic","title":"مرز نقش سالم و رفتار آسیب‌زا","lead":"یک نقش کارکردی می‌تواند با برداشت نادرست به رفتاری وابسته‌ساز یا قدرت‌محور تبدیل شود.","blocks":[{"title":"چهار لغزش","text":"Boss با تمرکز بر حفظ قدرت و ایجاد ترس به Tyrant نزدیک می‌شود. Coach با سؤال‌پرسیدن بی‌پایان و نپذیرفتن مسئولیت نتیجه به «درمانگر همیشگی» تبدیل می‌شود. Partner اگر هماهنگی عاطفی را بر اختلاف‌نظر محتوایی مقدم کند، به Best Friend می‌لغزد. Enabler اگر مسئله را دائماً از فرد بگیرد، وابستگی می‌سازد."},{"title":"معیار عملی","text":"آیا رفتار شما به انجام کار، توان و مسئولیت‌پذیری کمک می‌کند یا به کنترل قدرت، فرار از تصمیم، حفظ صمیمیت به هر قیمت یا نجات‌دادن مداوم؟ رهاکردن و بی‌تفاوتی هم نقش توانمندساز نیست."}],"source":{"chapter":"۷","pages":"۷۹–۸۲"},"prompt":"یک رفتار خودتان را انتخاب کنید که ممکن است از نقش سالم به نسخه آسیب‌زا نزدیک شود. چه تغییری مرز را روشن می‌کند؟","english":"Am I enabling capability or creating dependency?"},{"id":"lab","title":"آزمایشگاه نقش‌ها","lead":"در بانک موقعیت‌ها، انتخاب شما نام نقش را آشکار می‌کند؛ پاسخ درست ثابت برای نقش تعیین نمی‌شود.","blocks":[{"title":"شیوه تمرین","text":"یک موقعیت را انتخاب کنید و هر چهار پاسخ را بخوانید. یک پاسخ را با توجه به بافت خودتان ترجیح دهید؛ سپس یک گزینه دیگر را هم جدی بررسی کنید. دلیل انتخاب مهم‌تر از شمارش یک نقش است."},{"title":"پرسش مشاهده‌گر","text":"چه شرطی اگر تغییر کند، انتخاب شما عوض می‌شود؟ آیا مجوز و مسئولیت رسمیِ تصمیم روشن است؟ بخش تخصصی مسئله را به مسئول آن بسپارید؛ موضوع این تمرین، رفتار رهبری است."}],"source":{"chapter":"۷ و ۹","pages":"۷۸–۸۰، ۱۱۶–۱۱۹"},"tool":"cases","english":"What would make a different option more suitable?"},{"id":"output","title":"خروجی جلسه و مرور فهم","lead":"برای هر نقش، یک رفتار قابل‌مشاهده از کار خودتان بنویسید.","blocks":[{"title":"از برچسب به رفتار","text":"به‌جای «من کوچ هستم»، جمله‌ای بنویسید که در یک تصمیم واقعی می‌گویید و نشان دهید چه مسئولیتی نزد فرد می‌ماند. به‌جای «من توانمندسازم»، شرط یا قابلیتی را نام ببرید که فراهم می‌کنید."},{"title":"حد مسئولیت","text":"هیچ‌یک از چهار نقش، مسئولیت نهایی مدیر نسبت به نتیجه تیم را حذف نمی‌کند. اینکه فرد مسئول فکر و پیشنهاد باشد، به معنای بی‌تفاوتی مدیر به نتیجه نیست."}],"source":{"chapter":"۷","pages":"۷۰، ۷۳–۸۲"},"prompt":"برای هر نقش، یک جمله و یک اقدام بنویسید؛ در کدام نقش بیشترین نیاز به تمرین دارید؟","english":"I take ownership of my role and its consequences."}],"checks":[{"question":"در معنای خاص این کتاب، Coach عمدتاً چه می‌کند؟","options":["پاسخ تخصصی و توصیه آماده می‌دهد.","با پرسش، فکر و خودتنظیمی فرد را مطالبه می‌کند.","مسئولیت نتیجه تیم را واگذار و کنار می‌رود."],"correct":1,"why":"Coach بر مسئولیت و توان فکرکردن فرد تکیه دارد؛ با نقش آموزگار یا مراقبت افراطی یکی نیست."},{"question":"تفاوت Partner با نسخه آسیب‌زای «دوست صمیمی» چیست؟","options":["Partner باید هر اختلاف نظری را حذف کند.","هر دو نقش، حفظ صمیمیت را هدف اصلی می‌دانند.","Partner برای حل مسئله، اختلاف‌نظر محتوایی سازنده را هم وارد گفت‌وگو می‌کند."],"correct":2,"why":"همراهی با تیم به معنای برتری هماهنگی عاطفی بر کیفیت تصمیم نیست."}]},{"id":5,"title":"تعریف ترکیب نقش‌های مناسب","subtitle":"برداشت من، نه نتیجه یک تست","coverage":"فصل ۸ · ص ۸۵–۱۰۵","output":"ترکیب ده‌امتیازی نقش‌ها با استدلال بافتی و شرایط تغییر نقش","sections":[{"id":"context-situation","title":"بافت پایدار و موقعیت استثنایی","lead":"پیش‌بینی‌پذیری با انعطاف تعارض ندارد؛ برای تفاوت آن‌ها باید دلیل داشته باشید.","blocks":[{"title":"نقش اصلی و فرعی","text":"بافت نسبتاً پایدار، نقش یا نقش‌های اصلی شما را شکل می‌دهد. یک وضعیت غیرمعمول ممکن است نقش فرعی را لازم کند. این تغییر با عوض‌کردن روزانه شیوه بر اساس حال‌وهوای مدیر فرق دارد."},{"title":"نمونه صبا نفت","text":"در جلسه معمول بررسی گزینه‌های یک مسئله مبهم، نقش Partner می‌تواند قابل‌دفاع باشد. یک وضعیت فوری ممکن است به تصمیم روشن مسئول صاحب اختیار نیاز داشته باشد. صرف اینکه مدیر بی‌حوصله شده، دلیل کافی برای استثنایی‌نامیدن وضعیت نیست."}],"source":{"chapter":"۸","pages":"۸۶–۹۳"},"prompt":"در حوزه خود، یک وضعیت معمول و یک وضعیت واقعاً استثنایی بنویسید. چه چیزی تغییر نقش را برای تیم قابل‌توضیح می‌کند؟","english":"Is this an exception, or a familiar reaction under pressure?"},{"id":"no-formula","title":"از بافت به استدلال، نه فرمول","lead":"کتاب عمداً برای هر ترکیب نمره بافت، یک نقش قطعی تجویز نمی‌کند.","blocks":[{"title":"چرا فرمول نداریم؟","text":"بعدهای بافت در ترکیب با هم معنا پیدا می‌کنند. معنای یک بعد هم در حوزه‌های مختلف یکسان نیست. نویسنده پشتوانه تجربی کافی برای نگاشت قطعی شرایط به نقش‌ها ارائه نمی‌کند؛ بنابراین خروجی این دوره نیز «نقش توصیه‌شده توسط الگوریتم» ندارد."},{"title":"نقش خودِ مدیر","text":"علاقه شخصی به یک نقش کافی نیست؛ باید مناسبت آن با کار را توضیح دهید. در عین حال، شخصیت، تجربه و قابلیت شما در امکان اجرای آن اثر دارند. این‌ها پرسش‌های بازاندیشی‌اند، نه مجوز ساختن تیپ‌شناسی یا تشخیص شخصیت."}],"source":{"chapter":"۸","pages":"۹۲–۹۸"},"prompt":"برای نقش اصلی موردنظر، سه دلیل بافتی و یک محدودیت شخصی بنویسید. کدام دلیل ممکن است صرفاً ترجیح خودتان باشد؟","english":"What sits behind my preference?"},{"id":"capability","title":"آیا می‌خواهم و می‌توانم؟","lead":"مناسب‌بودن یک نقش با توان اجرای آن یکی نیست.","blocks":[{"title":"خواستن و توانستن","text":"آیا می‌توانید برای Partner بحث را تسهیل کنید و نظر شخصی را همیشه تحمیل نکنید؟ برای Coach از پاسخ آماده فاصله بگیرید؟ برای Enabler شرط لازم را بسازید و در جای لازم «نه» بگویید؟ این‌ها نمونه پرسش‌اند؛ فهرست قطعی و اعتبارسنجی‌شده شایستگی نیستند."},{"title":"کمک به رشد قابلیت","text":"اگر در نقشی مناسب ضعف دارید، یک موقعیت تمرین و حمایت مشخص انتخاب کنید. از همتا، مربی یا مدیر بالادست بازخورد بخواهید. هدف این نیست که برای حفظ تصویر مثبت از خودتان، بافت را طوری تفسیر کنید که نقش دلخواهتان درست از آب درآید."}],"source":{"chapter":"۸","pages":"۹۴–۹۸، ۱۰۲–۱۰۴"},"prompt":"در اجرای نقش اصلی، کدام قابلیت به تمرین نیاز دارد؟ چه موقعیت کوچکی برای تمرین و چه کسی برای بازخورد مناسب است؟","english":"What can I draw on, and what capability should I build?"},{"id":"mix","title":"ده امتیاز برای تعریف نقش","lead":"همان منطق تمرین کتاب: ده امتیاز را میان چهار نقش توزیع کنید.","blocks":[{"title":"سه چیز را جدا نگه دارید","text":"برداشت مناسب آینده شما، رفتاری که تاکنون از خود دیده‌اید و حدس شما درباره انتظار کارکنان، سه داده متفاوت‌اند. حدس مدیر، بازخورد واقعی کارکنان نیست. هیچ ترکیب نمونه‌ای به‌عنوان بهترین ترکیب از قبل پر نشده است."},{"title":"دلیل را ثبت کنید","text":"پس از رسیدن جمع به ۱۰، مشخص کنید نقش‌های اصلی کدام‌اند، چرا آن‌ها را متناسب می‌دانید و تحت چه شرایطی نقش دیگری می‌گیرید. ده امتیاز، ابزار بیان برداشت است و نمره علمیِ کیفیت یا شخصیت محسوب نمی‌شود."}],"source":{"chapter":"۸","pages":"۱۰۰–۱۰۴"},"tool":"mix","english":"This is my current working idea of leadership."},{"id":"attribution","title":"فرض من درباره انتظار کارکنان","lead":"نمی‌توان انتظارات کارکنان را نادیده گرفت یا صرفاً بر اساس آن‌ها نقش خود را تعیین کرد.","blocks":[{"title":"Role Attribution","text":"کارکنان ممکن است به‌خاطر تجربه قبلی از مدیر انتظار پاسخ نهایی داشته باشند. شما شاید نقش دیگری را مناسب بدانید. این فاصله نیاز به توضیح، گفت‌وگو و زمان دارد؛ خواست کارکنان به‌تنهایی نقش مناسب را تعیین نمی‌کند."},{"title":"فرض را آزمون کنید","text":"یک موقعیت معمول را با همکار مرور کنید: «در آن موقعیت از من چه انتظاری داشتی؟» قبل از شنیدن پاسخ، نتیجه را به‌جای او ننویسید. در جلسه بعد از همین تفاوت برای روشن‌کردن رابطه استفاده می‌کنیم."}],"source":{"chapter":"۸ و ۹","pages":"۹۸–۱۰۱، ۱۰۷–۱۱۱"},"prompt":"کدام انتظار را فقط حدس زده‌اید؟ با چه پرسش و در چه موقعیتی آن را بررسی می‌کنید؟","english":"What do you expect from me in this situation?"},{"id":"output","title":"بیانیه اولیه نقش من","lead":"برداشت خود را در چند جمله ساده و قابل‌فهم بنویسید.","blocks":[{"title":"الگوی نوشتن","text":"در این حوزه، معمولاً نقشِ ... را می‌گیرم، چون ... . از همکاران انتظار دارم ... . حمایت من ... است. اگر ... رخ دهد، نقش دیگری می‌گیرم و دلیل آن را روشن می‌گویم."},{"title":"معیار مرور","text":"آیا جمله‌ها درباره رفتار و مسئولیت‌اند یا فقط صفت‌های زیبا؟ آیا مدیر بالادست حدود این شیوه را می‌پذیرد؟ این بیانیه یک فرض کاری قابل‌اصلاح است و پس از گفت‌وگو با تیم تکمیل می‌شود."}],"source":{"chapter":"۸ و ۹","pages":"۱۰۰–۱۰۴، ۱۱۴–۱۱۶"},"prompt":"بیانیه اولیه خود را بنویسید؛ یک همتا کدام قسمت آن را مبهم می‌داند؟","english":"Let me make my role and expectations clear."}],"checks":[{"question":"در تمرین Role Mix، ده امتیاز چه چیزی را بیان می‌کند؟","options":["توزیع نسبی نقش‌ها در برداشت مدیر؛ همراه با استدلال و قابل‌اصلاح.","امتیاز هوش یا استعداد رهبری.","ترکیب درست مشترک برای همه مدیران شرکت."],"correct":0,"why":"این تمرین برای بیان و گفت‌وگو درباره نقش است، نه سنجش علمی شخصیت."},{"question":"کدام ادعا با فصل ۸ سازگار است؟","options":["برای هر نمره بافت، یک نقش قطعی وجود دارد.","شخصیت مدیر به‌تنهایی نقش مناسب را تعیین می‌کند.","بافت، قابلیت، شخصیت و انتظارهای نقش باید در یک بازاندیشی ترکیبی بررسی شوند."],"correct":2,"why":"کتاب نگاشت قطعی و ساده میان ابعاد و نقش‌ها را کنار می‌گذارد."}]},{"id":6,"title":"رابطه رهبری و روشن‌کردن انتظارها","subtitle":"تعریف نقش من، انتساب نقش از سوی تیم","coverage":"فصل ۹، بخش‌های ۱ تا ۴ · ص ۱۰۷–۱۱۹","output":"طرح گفت‌وگوی روشن‌سازی نقش و بررسی یک شکاف انتظار","sections":[{"id":"mismatch","title":"وقتی نیت خوب، تجربه متفاوت می‌سازد","lead":"ناسازگاری نقشِ تعریف‌شده و نقشِ موردانتظار می‌تواند رابطه را فرسوده کند.","blocks":[{"title":"دو برداشت از یک رفتار","text":"مدیر با پرسش «پیشنهادت چیست؟» قصد اعتماد دارد؛ همکار که منتظر Boss است، آن را بی‌توجهی می‌فهمد. یا مدیر همه مسائل را با دقت حل می‌کند، اما تیم متخصص آن را دخالت می‌بیند. برای فهم این رابطه، فقط نیت مدیر کافی نیست."},{"title":"دو بررسی جدا","text":"ابتدا بپرسید آیا برداشت مدیر با بافت مناسب است. سپس بپرسید آیا تیم این برداشت را می‌فهمد و چه انتظاری دارد. توافق بر یک نقش نامتناسب و داشتن نقش مناسبِ توضیح‌داده‌نشده، دو مسئله متفاوت‌اند."}],"source":{"chapter":"۹","pages":"۱۰۷–۱۱۱"},"prompt":"در یک موقعیت اخیر، نیت شما چه بود و همکار احتمالاً چه برداشتی کرد؟ کدام قسمت را می‌دانید و کدام قسمت هنوز فرض است؟","english":"Let me reflect that back to you."},{"id":"communicate","title":"نقش را با حرف و عمل منتقل کنیم","lead":"اعلام مشارکت و سپس تصمیم‌گیری یک‌طرفه، پیام متناقض می‌سازد.","blocks":[{"title":"گفت‌وگوی اولیه","text":"برای تیم توضیح دهید معمولاً چگونه تصمیم خواهید گرفت و چه انتظاری از آنان دارید. یک موقعیت آشنا را مثال بزنید. شرایط تغییر نقش و حدود اختیار را هم روشن کنید؛ صرف گفتن «از این پس توانمند باشید» کافی نیست."},{"title":"ثبات در اجرا","text":"عادت‌های قبلی تیم ممکن است مدتی ادامه یابد. در موقعیت‌های واقعی، برداشت خود را یادآوری کنید و واکنش آن‌ها را بشنوید. اگر قرار است تصمیم مشترک باشد، جلسه را به نمایش مشارکت پیش از تصمیم قطعی خودتان تبدیل نکنید."}],"source":{"chapter":"۹","pages":"۱۱۴–۱۱۶"},"prompt":"برای گفت‌وگوی ده‌دقیقه‌ای با تیم، سه پیام بنویسید: روش معمول تصمیم، سهم تیم و شرایط استثنا.","english":"Here is what you can expect from me.","photo":{"file":"sabanaft-meeting.jpg","alt":"جلسه پیمانکاران پروژه نیایش از وب‌سایت رسمی صبا نفت","caption":"جلسه پیمانکاران پروژه نیایش؛ تصویر رسمی شرکت. گفت‌وگوهای تمرینی دوره، گزارش این جلسه نیستند."}},{"id":"bias","title":"انتظارهای قالبی را وارد تعریف نقش نکنیم","lead":"قضاوت درباره نقش باید بر رفتار، بافت و مسئولیت باشد؛ نه کلیشه درباره زن و مرد یا پیشینه فرد.","blocks":[{"title":"نکته فصل ۹.۲","text":"کتاب نشان می‌دهد انتظارهای جنسیتی می‌توانند پذیرش رفتار مدیران زن را پیچیده کنند. این بحث، دستور تعیین نقش بر اساس جنسیت نیست. یافته‌ها و روایت‌های این بخش را نباید به طبیعت همه زنان یا مردان تعمیم داد."},{"title":"Case فرضی","text":"مدیر تازه یک پروژه، زن یا فردی با پیشینه متفاوت است. از رفتار قاطع او برداشت شخصیتی می‌شود، درحالی‌که همین تصمیم از مدیر قبلی عادی تلقی می‌شد. برای مرور، شواهد رفتار، اختیار و شرایط را مقایسه کنید؛ انتظارات ضمنی را آشکار کنید."}],"source":{"chapter":"۹","pages":"۱۱۱–۱۱۴"},"prompt":"آیا برای یک رفتار مشابه از دو مدیر، واژه‌های متفاوتی به کار برده‌اید؟ چه معیاری را می‌توان منصفانه برای هر دو بررسی کرد؟","english":"Which expectation may be shaping our judgment?"},{"id":"dialogue","title":"کارگاه روشن‌سازی رابطه","lead":"برای رسیدن به فهم مشترک، یک موقعیت واقعی را مبنا قرار دهید.","blocks":[{"title":"توالی گفت‌وگو","text":"۱) برداشت خود از نقش را توضیح دهید. ۲) از همکار بخواهید تجربه و انتظارش را در یک موقعیت مشخص بگوید. ۳) شباهت و تفاوت را روشن کنید. ۴) درباره رفتار قابل‌انتظار، مسئولیت و شرایط مراجعه توافق کنید."},{"title":"نمونه جمله","text":"«وقتی درباره این گزارش از تو پیشنهاد خواستم، می‌خواستم ارزیابی اولیه با تو بماند. از نگاه تو چه حمایتی کم بود؟ بیاییم روشن کنیم کدام تصمیم با توست و در چه وضعیتی باید با هم بررسی کنیم.»"}],"source":{"chapter":"۹","pages":"۱۱۴–۱۱۹"},"tool":"perspectives","english":"What would help us work together more clearly?"},{"id":"output","title":"خروجی جلسه و پیگیری رابطه","lead":"یک توافق رفتاری کوچک از گفت‌وگو بیرون بیاورید.","blocks":[{"title":"توافق قابل‌اجرا","text":"برای مثال: «در درخواست‌های بررسی گزارش، تهیه‌کننده اول ارزیابی و پیشنهاد خود را می‌آورد؛ مدیر روشن می‌کند از کدام نقش پاسخ می‌دهد؛ ابهام اختیار همان ابتدا مطرح می‌شود.» این یک مثال است، نه قاعده لازم برای همه حوزه‌ها."},{"title":"زمان مرور","text":"پس از دو یا سه موقعیت مشابه، بپرسید آیا فهم مشترک بهتر شده است. ثبت تجربه واقعی کارکنان را با حدس خودتان مخلوط نکنید. روشن‌سازی نقش می‌تواند فردی یا در کارگاه تیمی انجام شود."}],"source":{"chapter":"۹","pages":"۱۱۵–۱۱۹"},"prompt":"چه رفتاری از طرف شما و چه رفتاری از طرف همکار قرار است تغییر کند؟ چه زمانی تجربه آن را مرور می‌کنید؟","english":"What will help us follow through?"}],"checks":[{"question":"اگر همکار پرسش‌های Coach را بی‌توجهی تلقی کند، چه چیزی باید بررسی شود؟","options":["فقط اینکه همکار قدرشناس نیست.","تناسب نقش با بافت و فاصله میان تعریف مدیر و انتظار همکار.","ضرورت کنارگذاشتن همیشگی نقش Coach."],"correct":1,"why":"این تجربه می‌تواند از ناسازگاری برداشت‌ها در رابطه ناشی شود؛ یک توضیح تک‌عاملی کافی نیست."},{"question":"بحث جنسیت در این دوره چگونه به کار می‌رود؟","options":["برای تعیین نقش مناسب همه زنان و مردان.","برای نمره‌دادن به ویژگی‌های ذاتی افراد.","برای بررسی کلیشه و انتظار ضمنی، با توجه به رفتار و بافت واقعی."],"correct":2,"why":"موضوع، اثر انتظارهای قالبی بر رابطه است؛ نقش بر اساس جنسیت تجویز نمی‌شود."}]},{"id":7,"title":"بازاندیشی، بازخورد و مدیر بالادست","subtitle":"برداشت رهبری را در عمل بیازماییم","coverage":"فصل ۹، بخش‌های ۵ تا ۷ · ص ۱۱۹–۱۲۶","output":"یک موقعیت تحلیل‌شده، گفت‌وگو با مدیر بالادست و طرح دریافت بازخورد","sections":[{"id":"upward","title":"رابطه مدیر با مدیر خودش","lead":"مدیر میانی هم رهبری می‌کند و هم رهبری می‌شود.","blocks":[{"title":"انتظار پنهان در دستور","text":"وقتی مدیر بالادست می‌گوید «من تصمیم گرفته‌ام؛ اجرا کنید»، علاوه بر محتوای تصمیم ممکن است نقش شما در برابر تیم را هم تعیین کند. پیش از تعارض، روشن کنید کدام بخش تصمیم بسته است و کدام بخش برای مشارکت تیم باز مانده است."},{"title":"گفت‌وگوی نقش","text":"برداشت خود از بافت و نقش را با مدیر بالادست مطرح کنید. کتاب یک جدول قطعی برای موفق یا ناموفق‌بودن همه ترکیب‌های نقش در سلسله‌مراتب نمی‌دهد. هدف، فهم مشترک و روشن‌کردن حدود اجرای نقش است."}],"source":{"chapter":"۹","pages":"۱۱۹–۱۲۱"},"prompt":"کدام انتظار مدیر بالادست می‌تواند با نقش اصلی شما اصطکاک ایجاد کند؟ چه دو سؤال مشخصی باید با او مطرح شود؟","english":"What is decided, and where do we still have room to act?"},{"id":"pressure","title":"تغییر نقش یا بازگشت به عادت؟","lead":"هر فشار و ناراحتی را موقعیت استثنایی ننامیم.","blocks":[{"title":"واکنش مسلط","text":"رفتار بسیار تمرین‌شده در وضعیت تهدیدآمیز ممکن است خودکار برگردد. مدیری که سال‌ها Boss بوده و اکنون Partner را مناسب می‌داند، ممکن است با نخستین فشار، بحث را به نظر خودش ببندد. این رفتار باید بررسی شود؛ صرفاً با واژه «فوریت» توجیه نشود."},{"title":"مکث قابل‌تمرین","text":"نشانه فشار را در خود تشخیص دهید. از خود بپرسید چه چیزی واقعاً تغییر کرده، چه اختیاری دارید و چرا نقش تازه مناسب است. اگر تغییر نقش ضروری بود، دلیل و مدت آن را به تیم بگویید."}],"source":{"chapter":"۹","pages":"۱۲۱–۱۲۲"},"prompt":"در یک موقعیت پرفشار، چه نشانه‌ای در خودتان می‌بینید؟ دفعه بعد چه مکث یا جمله‌ای می‌تواند انتخاب شما را آگاهانه‌تر کند؟","english":"I notice I am returning to an old pattern."},{"id":"perspectives","title":"چهار دیدگاه را جدا ببینیم","lead":"خواست مدیر، خودمشاهده‌گری مدیر، انتظار کارکنان و تجربه کارکنان یک داده واحد نیستند.","blocks":[{"title":"چهار خانه متفاوت","text":"ممکن است مدیر بخواهد Partner باشد اما در عمل خود را Boss ببیند؛ کارکنان هم انتظار دیگری داشته باشند یا رفتار متفاوتی تجربه کنند. مقایسه این دیدگاه‌ها، موضوع گفت‌وگو درباره شکاف‌هاست و نباید به میانگین مبهم «رهبری خوب» تبدیل شود."},{"title":"مالکیت و کاربرد","text":"بازخورد برای یادگیری باید در خدمت بازاندیشی مدیر باشد. این صفحه ابزار اختصاصی یا اعتبارسنجی‌شده نویسنده را بازسازی نمی‌کند. ورود یادداشت کارکنان فقط ثبت دستی یک گفت‌وگوی واقعی با اطلاع آنان است؛ سامانه جمع‌آوری خودکار یا ارزیابی رسمی کارکنان نیست."}],"source":{"chapter":"۹","pages":"۱۲۲–۱۲۵"},"tool":"perspectives","english":"What do I intend, and what do others experience?"},{"id":"peer","title":"Peer Coaching با موقعیت واقعی","lead":"یک همتا می‌تواند به دیدن گزینه‌ای که از قلم افتاده کمک کند.","blocks":[{"title":"شش محور مرور","text":"موقعیت چه بود؟ چالش چه بود؟ چه کردید و چه پیامدی دیدید؟ کدام برداشت از نقش راهنمای شما بود؟ چه گزینه معقول دیگری داشتید؟ از نقش دیگر چه رفتاری ممکن بود؟"},{"title":"کیفیت گفت‌وگو","text":"همتا به‌جای نسخه فوری، به روشن‌شدن فرض‌ها، نقش و شواهد کمک کند. تحلیل درباره رفتار رهبری باشد؛ نه داوری درباره شخصیت یا ارائه راه‌حل تخصصی نامطمئن برای پروژه."}],"source":{"chapter":"۹ و پیوست","pages":"۱۲۱–۱۲۲، ۱۵۹–۱۶۰"},"tool":"journal","english":"What alternative might be worth exploring?"},{"id":"output","title":"چرخه شخصی بازاندیشی","lead":"یک بازه مرور انتخاب کنید و یک تجربه را کامل دنبال کنید.","blocks":[{"title":"قرار عملی","text":"یک موقعیت تکرارشونده، یک رفتار موردنظر، یک شاهد نتیجه و یک همتای مرور را مشخص کنید. زمان بازبینی را در برنامه خودتان بنویسید. ثبت تاریخ در این ابزار به‌تنهایی یادآور یا دعوت تقویمی ایجاد نمی‌کند."},{"title":"معیار یادگیری","text":"پرسش فقط این نیست که «بیشتر Coach شده‌ام؟»؛ بپرسید آیا برداشت رهبری با بافت متناسب‌تر، برای تیم روشن‌تر و در رفتار قابل‌مشاهده‌تر شده است؟ چه چیزی نیاز به اصلاح دارد؟"}],"source":{"chapter":"۹ و ۱۱","pages":"۱۲۱–۱۲۶، ۱۴۳–۱۴۷"},"prompt":"چه کسی به شما بازخورد می‌دهد، درباره چه رفتاری و در چه زمانی؟ چه چیزی را در مرور بعدی تغییر خواهید داد؟","english":"What is the next best step?"}],"checks":[{"question":"کدام مورد «بازخورد تجربه‌شده کارکنان» است؟","options":["حدس مدیر درباره اینکه کارکنان چه دیده‌اند.","آنچه کارکنان واقعاً درباره تجربه رفتار مدیر بیان کرده‌اند.","نقش دلخواه مدیر برای آینده."],"correct":1,"why":"چهار دیدگاه باید تفکیک شوند؛ حدس مدیر جای داده کارکنان را نمی‌گیرد."},{"question":"بازگشت به نقش قبلی زیر فشار را چگونه مرور کنیم؟","options":["بررسی کنیم شرایط واقعاً استثنایی بود یا عادت قدیمی خودکار برگشت.","هر بار آن را اثبات درست‌بودن نقش قبلی بدانیم.","همیشه هر تغییر نقش را نادرست بدانیم."],"correct":0,"why":"کتاب امکان تغییر موجه نقش و خطر واکنش مسلط را از هم جدا می‌کند."}]},{"id":8,"title":"ابزارهای سازگار با برداشت رهبری","subtitle":"از فایده موردنظر به طراحی ابزار","coverage":"فصل ۱۰ · ص ۱۲۷–۱۴۲","output":"طرح یک ابزار با فایده، بافت، نقش، مسئول و شیوه مرور روشن","sections":[{"id":"benefit","title":"اول فایده، بعد ابزار","lead":"قبل از ساخت فرم یا Dashboard بپرسیم چه نیازی باید پاسخ بگیرد.","blocks":[{"title":"چهار گام طراحی","text":"فایده موردنظر را روشن کنید؛ بافت و برداشت رهبری را بررسی کنید؛ ابزار متناسب را انتخاب کنید؛ سپس جزئیات اجرای آن را طراحی کنید. شروع از ابزار می‌تواند به فرایندی برسد که فقط به‌خاطر سرمایه‌گذاری قبلی ادامه می‌یابد."},{"title":"یک مثال","text":"اگر مسئله، نامشخص‌بودن سهم دو واحد در یک تحویل است، افزودن امتیاز عملکرد لزوماً کمک نمی‌کند. شاید روشن‌سازی انتظار و مسئولیت، منفعت اصلی باشد. انتخاب ابزار به همان منفعت و رابطه رهبری وابسته است."}],"source":{"chapter":"۱۰","pages":"۱۲۷–۱۳۲"},"tool":"benefits","english":"What benefit are we trying to achieve?"},{"id":"expectations","title":"انتظار عملکرد؛ استاندارد، هدف یا OKR؟","lead":"به نام ابزار تکیه نکنید؛ ماهیت کار را بررسی کنید.","blocks":[{"title":"انتظار روشن، شکل‌های متفاوت","text":"برای کار تکراری با نتیجه و روش روشن، استاندارد مشترک می‌تواند معنادارتر از هدف فردی ساختگی باشد. در کار مبهم و درهم‌تنیده، اولویت و نتایج میانیِ قابل‌بازنگری مطرح می‌شود. کتاب OKR را در چنین بافت‌هایی و با تدوین مشارکتی توضیح می‌دهد."},{"title":"تناسب نقش و اختیار","text":"می‌توان انتظار را از نقش Boss روشن کرد یا با تیم، از نقش Coach/Partner به تعریف مشترک رسید. این تفاوت با حذف معیار کیفیت یا کنارگذاشتن الزامات مصوب یکی نیست. در روایت کتاب، اتصال نتایج بلندپروازانه OKR به پرداخت متغیر توصیه نمی‌شود."}],"source":{"chapter":"۱۰","pages":"۱۳۳–۱۳۴"},"prompt":"برای فعالیت منتخب شما، استاندارد روشن‌تر است یا هدف قابل‌تعیین یا نتیجه‌ای که باید در مسیر یادگیری بازنگری شود؟ چرا؟","english":"What does good performance mean in this context?"},{"id":"performance","title":"نیازها، عملکرد ضعیف و تقدیر","lead":"همه مقصودهای عملکردی را در یک گفت‌وگو و یک امتیاز ادغام نکنیم.","blocks":[{"title":"نیاز و افت عملکرد","text":"کمبود عملکرد را به‌موقع بررسی کنید. توان و منابع، انگیزه و معنا، و امکان عمل در حدود اختیار را جدا ببینید. درباره اقدام و حمایت توافق و پیشرفت را مرور کنید. این بحث جای تصمیم‌های رسمی یا فرآیندهای لازم شرکت را نمی‌گیرد."},{"title":"عملکرد ممتاز و نقش قضاوت","text":"تقدیر از عملکرد ممتاز با رسیدگی به افت عملکرد پیامد یکسان ندارد. قضاوت رسمیِ مرتبط با پرداخت، از بازخورد یادگیری متفاوت است و ممکن است با نقش اصلی مدیر اصطکاک داشته باشد. نمونه‌های کتاب مانند هیئت بررسی یا مرجع بالاتر، گزینه‌های طراحی‌اند؛ نه مجوز تصمیم‌گیری خارج از اختیار شما."}],"source":{"chapter":"۱۰","pages":"۱۳۵–۱۳۷"},"prompt":"در ابزار فعلی، کدام هدف‌ها مخلوط شده‌اند؟ رسیدگی به نیاز، بازخورد یادگیری و قضاوت رسمی را چگونه از هم روشن‌تر می‌کنید؟","english":"What is this conversation meant to accomplish?"},{"id":"learning","title":"بازخورد، یادگیری و استعداد","lead":"مالکیت یادگیری نزد یادگیرنده و دریافت‌کننده بازخورد بماند.","blocks":[{"title":"بازخورد با تحسین و حکم فرق دارد","text":"تشکر، دستور، قضاوت رسمی و بازخورد یکسان نیستند. کتاب بر جست‌وجوی فعال بازخورد و مالکیت دریافت‌کننده تأکید می‌کند. در معنای خاص نقش‌های همین کتاب، Coach به‌جای ارائه بازخورد، با پرسش به خودارزیابی کمک می‌کند؛ Partner می‌تواند بازخورد متقابل ردوبدل کند و فراهم‌کردن بازخورد می‌تواند جزئی از نقش Enabler باشد. این تمایز را نباید حکم کلی درباره همه مکاتب کوچینگ دانست. گفت‌وگوی شریک بازخورد یا Retrospective می‌تواند به بررسی آنچه باید ادامه یابد یا تغییر کند کمک کند."},{"title":"رشد و استعداد","text":"در گفت‌وگوی یادگیری، چالش و نیاز رشد را با خود فرد بررسی کنید؛ Coach با پرسش به برنامه خودراهبر کمک می‌کند و Enabler شرایط را فراهم می‌سازد. برای استعدادها نیز کتاب گفت‌وگوی جدی مدیران درباره توان و مسئولیت آینده را به‌عنوان یک گزینه مطرح می‌کند، نه الزام یک فرم واحد."}],"source":{"chapter":"۱۰","pages":"۱۳۸–۱۴۰"},"prompt":"برای یک چالش واقعی، چه کسی باید بازخورد بخواهد و از چه کسی؟ چه فعالیت یادگیری و حمایتی می‌تواند به بهبود کار کمک کند؟","english":"From whom could I seek useful feedback?"},{"id":"design","title":"طراحی ابزارِ خودتان","lead":"فایده و سازگاری را پیش از جزئیات اجرایی ثبت کنید.","blocks":[{"title":"چه چیزهایی باید مشخص باشد؟","text":"فایده، حوزه، نقش مدیر، مشارکت کارکنان، آغازکننده، زمان استفاده، مالک یادداشت‌ها و شیوه مرور را روشن کنید. اگر بخشی از ابزار قضاوت رسمی یا تأیید سازمانی می‌خواهد، همان را صریح بنویسید."},{"title":"از استاندارد تا Navigation","text":"کتاب سه منطق استفاده از ابزار را مقایسه می‌کند: روش استاندارد، جعبه‌ابزار متنوع و انتخاب/طراحی منعطف بر اساس بافت. ابزار منعطف هم به هدف روشن و مسئولیت اجرا نیاز دارد؛ صرفاً حذف فرم نیست."}],"source":{"chapter":"۱۰","pages":"۱۳۰–۱۳۲، ۱۴۰–۱۴۱"},"tool":"tool-design","english":"Let’s design around the purpose."},{"id":"output","title":"یک آزمایش کوچک و قابل‌مرور","lead":"ابزار را ابتدا در یک موقعیت محدود و مجاز بیازمایید.","blocks":[{"title":"آزمایش پیشنهادی","text":"برای مثال، در یک مرور پیشرفت، ابتدا روشن کنید هدف حل مسئله است یا ارزیابی رسمی. برداشت خود از نقش را بگویید و از تیم بخواهید تناسب شیوه جلسه را با هدف بررسی کند. به قوانین و اختیار واقعی همان موقعیت پایبند بمانید."},{"title":"مرور نتیجه","text":"آیا منفعت موردنظر به دست آمد؟ نقش‌ها روشن بود؟ مالکیت یادگیری حفظ شد؟ چه هزینه یا اثر ناخواسته‌ای داشت؟ ابزار را بر اساس این شواهد اصلاح کنید؛ نه بر اساس جذابیت نام یا ظاهر آن."}],"source":{"chapter":"۱۰","pages":"۱۲۹–۱۴۲"},"prompt":"یک ابزار را در چه دامنه‌ای، با چه موافقت لازم و تا چه زمانی می‌آزمایید؟ موفقیت آن با چه شاهدی بررسی می‌شود؟","english":"What will tell us whether this is working?"}],"checks":[{"question":"ترتیب طراحی سازگار با فصل ۱۰ کدام است؟","options":["ابزار، ظاهر، اجبار به اجرا، یافتن فایده.","فایده، بافت و برداشت رهبری، انتخاب ابزار، طراحی اجرا.","انتخاب نرم‌افزار و سپس یکسان‌سازی همه تیم‌ها."],"correct":1,"why":"کتاب طراحی را از فایده موردانتظار و تناسب با بافت شروع می‌کند."},{"question":"بازخورد یادگیری و قضاوت رسمی چه رابطه‌ای دارند؟","options":["همیشه یکسان‌اند.","فقط نامشان فرق دارد و پیامدشان یکی است.","هدف، مالکیت و پیامد متفاوت دارند و باید روشن از هم تفکیک شوند."],"correct":2,"why":"کتاب به خودتنظیمی و مالکیت دریافت‌کننده در بازخورد و پیامد بیرونی قضاوت اشاره می‌کند."}]},{"id":9,"title":"آزمایشگاه موقعیت‌ها و تداوم عمل","subtitle":"برداشت رهبری را در کار واقعی زنده نگه داریم","coverage":"فصل ۱۱ · ص ۱۴۳–۱۴۷؛ پیوست ۱۵۳–۱۶۰","output":"نقشه شخصی رهبری، مرور موقعیت‌ها و برنامه پیگیری","sections":[{"id":"integration","title":"نقشه شخصی خود را یکپارچه کنید","lead":"بافت، ترکیب نقش، انتظارها و ابزار را کنار هم ببینید.","blocks":[{"title":"مرور کل مسیر","text":"کدام ویژگی بافت برای شما تعیین‌کننده بود؟ چه نقش‌هایی را اصلی می‌دانید؟ کارکنان چه انتظاری دارند؟ مدیر بالادست چه حدودی می‌گذارد؟ کدام ابزار با این برداشت سازگار است؟ پاسخ‌ها باید یکدیگر را توضیح دهند."},{"title":"معیار پیشرفت","text":"هدف این دوره رسیدن همه مدیران به یک شکل واحد نیست. پیشرفت یعنی برداشت متناسب‌تر و روشن‌تر، رابطه قابل‌فهم‌تر و رفتار آگاهانه‌تر. این فرایند با اتمام جلسات پایان نمی‌یابد."}],"source":{"chapter":"۱۱ و پیوست","pages":"۱۴۳–۱۴۷، ۱۵۹–۱۶۰"},"prompt":"بزرگ‌ترین ناسازگاری فعلی میان بافت، نقش، انتظار و ابزار شما کجاست؟","english":"How do these pieces fit together?","photo":{"file":"sabanaft-site.webp","alt":"بازدید از پروژه نیایش صبا نفت","caption":"بازدید پروژه نیایش؛ تصویر واقعی منتشرشده در وب‌سایت رسمی صبا نفت. موقعیت‌های تمرین، تألیف آموزشی‌اند."}},{"id":"cases","title":"۱۵ موقعیت، چهار پاسخ معقول","lead":"همه موقعیت‌ها را با فرض بافت یکسان پاسخ ندهید.","blocks":[{"title":"بانک تمرین اختصاصی صبا نفت","text":"موضوع‌های پیوست کتاب با موقعیت‌های فرضی ستاد، پروژه و همکاری پیمانکاران بازنویسی شده‌اند. پاسخ‌ها رفتار چهار نقش را نشان می‌دهند. انتخاب نقش، کلید درست ثابت ندارد و از آن نمره شخصیت یا کیفیت مدیریت ساخته نمی‌شود."},{"title":"گام مهم پس از انتخاب","text":"از میان چهار پاسخ، دو مورد را جدی مقایسه کنید. یک شاهد بافتی، یک محدودیت اختیار و یک شرط تغییر انتخاب بنویسید. اگر دو نفر متفاوت انتخاب کردند، ابتدا تفاوت فرض‌هایشان را بشنوید."}],"source":{"chapter":"۹ و پیوست","pages":"۱۱۶–۱۱۹، ۱۵۳–۱۵۸"},"tool":"cases","english":"What assumptions make each option reasonable?"},{"id":"review","title":"از انتخاب موردی به یادگیری","lead":"تعداد انتخاب‌ها را با برداشت اعلام‌شده مقایسه کنید؛ آن را تست شخصیت ننامید.","blocks":[{"title":"مقایسه قابل‌گفت‌وگو","text":"اگر در موارد مختلف بیشتر Boss انتخاب کرده‌اید، ممکن است بافت را پرریسک دیده باشید یا عادت قبلی فعال شده باشد؛ از شمارش به‌تنهایی نمی‌توان نتیجه گرفت. به دلایل ثبت‌شده و تفاوت موقعیت‌ها برگردید."},{"title":"مرور با همتا","text":"یک مورد را که با نقش اصلی شما متفاوت است انتخاب کنید. آیا استثنا موجه بود؟ چه انتخاب معقول دیگری داشتید؟ اگر تیم از شما نقش دیگری انتظار داشته باشد، چه گفت‌وگویی لازم می‌شود؟"}],"source":{"chapter":"۸ و ۹","pages":"۸۸–۹۳، ۱۱۷–۱۲۲"},"tool":"case-summary","english":"What have these choices helped me notice?"},{"id":"plan","title":"برنامه عمل و بازاندیشی","lead":"یک تغییر کوچک با موقعیت، شاهد و زمان مرور روشن انتخاب کنید.","blocks":[{"title":"چه چیزی را تمرین می‌کنم؟","text":"رفتار موردنظر را مشخص کنید؛ مثلاً «در مرور ایده، پیش از ارزیابی خودم، از تهیه‌کننده منطق و پیشنهادش را می‌پرسم». روشن کنید این رفتار از کدام نقش می‌آید و چرا با بافت شما متناسب است."},{"title":"حمایت و پیگیری","text":"برای بازخورد یک همتا یا همکار مشخص کنید، حدود اختیار را روشن نگه دارید و زمان مرور تعیین کنید. دفتر بازاندیشی برای ثبت تجربه است؛ برنامه زمانی یا داده‌ها به‌طور خودکار برای شخص دیگری ارسال نمی‌شوند."}],"source":{"chapter":"۹ و پیوست","pages":"۱۲۱–۱۲۶، ۱۵۹–۱۶۰"},"tool":"plan","english":"What will help me keep momentum?"},{"id":"output","title":"بازگشت به مسیر، نه پایان یادگیری","lead":"دستاورد این دوره یک برداشت قابل‌توضیح و قابل‌اصلاح از رهبری است.","blocks":[{"title":"بسته شخصی شما","text":"نقشه بافت، ترکیب نقش‌ها، یادداشت مقایسه انتظارها، دلایل انتخاب موقعیت‌ها و برنامه عمل در همین مرورگر نگهداری می‌شوند. می‌توانید آن‌ها را برای ادامه کار شخصی دریافت یا چاپ کنید."},{"title":"مرور نهایی","text":"وقتی بافت، تیم یا اختیار تغییر کرد، به نقشه برگردید. وقتی تجربه کارکنان با نیت شما فاصله داشت، رابطه را روشن کنید. وقتی ابزار کار نمی‌کرد، ابتدا فایده و سازگاری‌اش را دوباره بررسی کنید."}],"source":{"chapter":"۱۱ و پیوست","pages":"۱۴۳–۱۴۷، ۱۵۹–۱۶۰"},"tool":"portfolio","english":"What are you taking away, and how will you follow through?"}],"checks":[{"question":"از فراوانی انتخاب چهار نقش در ۱۵ موقعیت چه می‌توان فهمید؟","options":["داده‌ای برای گفت‌وگو درباره دلایل و تفاوت بافت‌ها.","تیپ شخصیتی قطعی مدیر.","رتبه رسمی مدیران شرکت."],"correct":0,"why":"شمارش انتخاب‌ها ابزار بازاندیشی است و تفسیر آن به دلایل و بافت نیاز دارد."},{"question":"بعد از پایان جلسات چه چیزی باید ادامه یابد؟","options":["تکرار یک نقش برای همیشه.","انتظار برای آزمون رتبه‌بندی سال بعد.","مرور تناسب برداشت رهبری با بافت، رابطه و رفتار واقعی."],"correct":2,"why":"در فصل پایانی، رهبری مسیر مداوم یادگیری و بازاندیشی است."}]}],"roles":[{"id":"B","en":"Boss","fa":"تصمیم‌گیر و هدایت‌کننده","focus":"من تصمیم و جهت را روشن می‌کنم.","responsibility":"مدیر برای مسئله یا نتیجه، انتظار و مسیر مشخص ارائه می‌کند و اجرای آن را پیگیری می‌کند.","example":"«پس از بررسی، این مسیر را انتخاب می‌کنم؛ مسئول و موعد اجرا این است.»","boundary":"داشتن پاسخ و پیگیری مسئولانه با ایجاد ترس و حفظ قدرت به هر قیمت فرق دارد.","toxic":"Tyrant · قدرت‌محوری و ترساندن","source":"فصل ۷، ص ۷۰–۷۳، ۸۰–۸۲"},{"id":"C","en":"Coach","fa":"برانگیزاننده فکر و خودتنظیمی","focus":"تو تحلیل و پیشنهاد خودت را می‌سازی.","responsibility":"مدیر با پرسش‌های جدی، فرد یا تیم را به ارزیابی، انتخاب و مسئولیت‌پذیری دعوت می‌کند.","example":"«پیشنهادت چیست؟ بر چه شواهدی تکیه دارد و چه چیزی می‌تواند آن را نامناسب کند؟»","boundary":"پرسش‌گری، مجوز بی‌پاسخ‌گذاشتن نیاز واقعی یا فرار از مسئولیت نتیجه تیم نیست.","toxic":"Perpetual Therapist · پرسش‌گری بی‌پایان و نپذیرفتن موضع","source":"فصل ۷، ص ۷۳–۷۴، ۸۱–۸۲"},{"id":"P","en":"Partner","fa":"شریک در تصمیم و حل مسئله","focus":"ما با هم بررسی و تصمیم می‌گیریم.","responsibility":"مدیر عضو و تسهیل‌گر تیم است؛ دیدگاه‌ها را وارد تصمیم می‌کند و مسئولیت را به‌طور مشترک پیش می‌برد.","example":"«بیایید گزینه‌ها را با هم بررسی کنیم و به تصمیم مشترک برسیم.»","boundary":"همراهی، حذف اختلاف‌نظر برای حفظ صمیمیت نیست؛ موضوع کار باید جدی بررسی شود.","toxic":"Best Friend · صمیمیت به قیمت بحث محتوایی","source":"فصل ۷، ص ۷۵–۷۶، ۸۱"},{"id":"E","en":"Enabler","fa":"فراهم‌کننده قابلیت و شرایط","focus":"شرایطی بسازم که آنان بتوانند کار کنند.","responsibility":"مدیر روی منابع، یادگیری، قواعد همکاری و رفع موانع ساختاری تمرکز می‌کند تا افراد مستقل‌تر عمل کنند.","example":"«برای ارزیابی و پیشبرد این موضوع چه دسترسی، مهارت یا هماهنگی‌ای لازم دارید؟»","boundary":"حمایت باید قابلیت بسازد؛ گرفتن دائمی مسئله از افراد می‌تواند وابستگی را حفظ کند.","toxic":"Overprotective Mother · حمایت افراطی و وابسته‌سازی","source":"فصل ۷، ص ۷۶–۷۷، ۸۱–۸۲"}],"dimensions":[{"id":"certainty","group":"task","title":"قطعیت کار","low":"نتیجه و روش روشن","high":"نتیجه و مسیر در حال کشف","hint":"برای یک فعالیت مشخص، میزان روشنی خروجی و راه انجام آن را بررسی کنید؛ همه کارهای یک پروژه لزوماً مبهم نیستند.","pages":"۴۸–۴۹، ۱۴۹"},{"id":"responsibility","group":"task","title":"سطح مسئولیت","low":"غالباً راهبردی","high":"غالباً عملیاتی","hint":"آینده و چارچوب کلی سازمان یا تصمیم‌های اجرایی و مسائل روزمره؟ این دو می‌توانند هم‌زمان وجود داشته باشند.","pages":"۴۹–۵۰، ۱۴۹"},{"id":"time","group":"task","title":"فشار ساختاری زمان","low":"فرصت بررسی دقیق","high":"نیاز مداوم به تصمیم سریع","hint":"ویژگی پایدار کار را ببینید؛ یک موعد فشرده منفرد، تمام بافت را تعیین نمی‌کند.","pages":"۵۰، ۱۴۹"},{"id":"motivation","group":"people","title":"برداشت از انگیزش","low":"بیشتر پاداش و هدایت بیرونی","high":"بیشتر معنا و مسئولیت‌پذیری درونی","hint":"این برداشت مدیر است؛ آن را با شاهد و گفت‌وگو بررسی کنید و به شخصیت ثابت فرد تبدیل نکنید.","pages":"۵۰–۵۱، ۱۵۰"},{"id":"replaceability","group":"people","title":"جایگزین‌پذیری حرفه‌ای","low":"جایگزینی نسبتاً آسان‌تر","high":"جایگزینی دشوارتر و گزینه‌های بیرونی بیشتر","hint":"درباره مهارت و بازار کار است؛ ارزش انسانی افراد با این مقیاس سنجیده نمی‌شود.","pages":"۵۱، ۱۵۰"},{"id":"individuality","group":"people","title":"فردیت و تنوع","low":"همانندیِ بیشتر دیدگاه و تجربه","high":"تفاوت بیشتر دیدگاه و تجربه","hint":"به مجازبودن و استفاده از تفاوت‌ها توجه کنید؛ صرف شمارش ویژگی‌های جمعیتی کافی نیست.","pages":"۵۲، ۱۵۰"},{"id":"expertise","group":"people","title":"جایگاه دانش تخصصی","low":"مدیر در اغلب جزئیات متخصص‌تر","high":"افراد در حوزه خود متخصص‌تر","hint":"دید کلی مدیر را از برتری تخصصی در هر حوزه جدا کنید.","pages":"۵۲–۵۳، ۱۵۰"},{"id":"distance","group":"team","title":"فاصله مکانی","low":"هم‌مکانی بیشتر","high":"پراکندگی و هماهنگی از راه دور","hint":"شیوه واقعی همکاری و امکان ارتباط مستقیم را بررسی کنید.","pages":"۵۴، ۱۵۰"},{"id":"influence","group":"team","title":"مبنای نفوذ","low":"اختیار رسمی و مستقیم","high":"نفوذ تخصصی با اختیار محدودتر","hint":"در رابطه با پیمانکار یا تیم ماتریسی، مرز دستور و هماهنگی را روشن کنید.","pages":"۵۴–۵۵، ۱۵۰"},{"id":"dependence","group":"team","title":"وابستگی در کار","low":"خروجی‌های نسبتاً مستقل","high":"وابستگی زیاد کارها به هم","hint":"آیا خروجی یک نفر ورودی فرد دیگر است و موفقیت به کل سیستم وابسته است؟","pages":"۵۵–۵۶، ۱۵۰"},{"id":"span","group":"team","title":"وسعت نظارت","low":"گزارش‌دهندگان مستقیم بیشتر","high":"گزارش‌دهندگان مستقیم کمتر","hint":"اثر تعداد بر زمان و توجه فردی را بسنجید؛ این مقیاس عدد بهینه جهان‌شمول نمی‌دهد.","pages":"۵۶، ۱۵۰"},{"id":"cohesion","group":"team","title":"انسجام گروه","low":"هم‌بستگی و تعلق قوی‌تر","high":"هم‌بستگی و تعلق ضعیف‌تر","hint":"انسجام می‌تواند همکاری را تقویت کند و در عین حال خطر حذف نقد داشته باشد.","pages":"۵۶، ۱۵۱"},{"id":"trust","group":"team","title":"واکنش به رهبری","low":"پذیرش عمومی تصمیم‌ها","high":"پرسشگری سازنده بیشتر","hint":"پرسشگری را خودکار بی‌اعتمادی یا نامطلوب تلقی نکنید.","pages":"۵۷، ۱۵۱"},{"id":"commitment","group":"team","title":"جهت تعهد","low":"بیشتر رو به مدیر","high":"بیشتر رو به مشتری و همکار","hint":"در تصمیم دشوار، افراد نخست به رضایت چه کسی و اثر بر چه کسی فکر می‌کنند؟","pages":"۵۷–۵۸، ۱۵۱"},{"id":"groupTask","group":"team","title":"منطق نتیجه گروه","low":"وابسته‌تر به ضعیف‌ترین حلقه","high":"بهره‌مندتر از بهترین پیشنهاد","hint":"برای کار منتخب، تفاوت نیاز به تقویت حلقه محدودکننده و آزادکردن ایده ممتاز را بررسی کنید.","pages":"۵۸، ۱۵۱"},{"id":"boundaries","group":"organization","title":"مرز میان واحدها","low":"جدایی و جزیره‌ای‌بودن بیشتر","high":"ارتباط مستقیم بین واحدها بیشتر","hint":"وابستگی و تعامل واقعی را بررسی کنید، نه فقط نمودار سازمانی را.","pages":"۶۰–۶۱، ۱۵۱"},{"id":"relevance","group":"organization","title":"کانون اهمیت راهبردی","low":"خلق مزیت از عملکرد ممتاز","high":"پیشگیری از خسارت جدی","hint":"دو کانون فصل را مقایسه کنید؛ ممکن است هر دو برای فعالیت شما مهم باشند. این موضوع را در شاهد توضیح دهید، نه با یک عدد تنها.","pages":"۵۹–۶۰، ۱۵۱"},{"id":"autonomy","group":"organization","title":"دامنه استقلال","low":"قواعد و تأییدهای بالادستی بیشتر","high":"آزادی تصمیم بیشتر در چارچوب اختیار","hint":"درجه واقعی استقلال را ثبت کنید؛ این مقیاس مجوز تغییر حدود اختیار نیست.","pages":"۶۱، ۱۵۱"}],"benefits":[{"id":"expect","title":"روشن‌کردن انتظار عملکرد","question":"چه چیزی باید در نتیجه یا معیار انجام کار روشن شود؟","examples":"گفت‌وگوی استاندارد مشترک، توافق هدف، یا بازنگری نتایج میانی؛ انتخاب بر اساس ماهیت کار.","pages":"۱۳۳–۱۳۴"},{"id":"needs","title":"شناخت و پاسخ به نیازها","question":"چه شرایطی مانع کار یا شکوفایی قابلیت می‌شود؟","examples":"گفت‌وگوی نیاز، کارگاه توسعه تیم یا Walk & Talk؛ همراه با پیگیری قابل‌انجام.","pages":"۱۳۵–۱۳۶"},{"id":"reward","title":"دیده‌شدن عملکرد ممتاز","question":"چگونه سهم ممتاز را با شواهد ببینیم و مرجع تصمیم را روشن کنیم؟","examples":"مرور شواهد از مسیر مجاز، بررسی جمعی یا مرجع بالاتر؛ با تفکیک یادگیری از قضاوت رسمی.","pages":"۱۳۶–۱۳۷"},{"id":"poor","title":"رسیدگی به افت عملکرد","question":"مسئله توان، انگیزه یا امکان عمل چیست و چه پیگیری لازم است؟","examples":"گفت‌وگوی به‌موقع، توافق اقدام و حمایت، و مرور پیشرفت؛ با رعایت فرایند لازم شرکت.","pages":"۱۳۷"},{"id":"feedback","title":"دادن و گرفتن بازخورد","question":"چه کسی برای بهبود کار به بازخورد چه کسی نیاز دارد؟","examples":"شریک بازخورد یا Retrospective؛ مالکیت دریافت‌کننده و هدف یادگیری روشن بماند.","pages":"۱۳۸–۱۳۹"},{"id":"learning","title":"روشن‌کردن و برنامه‌ریزی یادگیری","question":"کدام چالش، چه نیاز یادگیری و چه فعالیتی را معنادار می‌کند؟","examples":"گفت‌وگوی یادگیری با پرسش‌های Coach و فراهم‌کردن حمایت از نقش Enabler.","pages":"۱۳۹"},{"id":"talent","title":"شناخت، رشد و نگهداشت استعداد","question":"چه قابلیت و مسئولیت آینده‌ای ارزش توجه بیشتری دارد؟","examples":"گفت‌وگوی مستند و جدی مدیران درباره افراد و فرصت‌های رشد؛ بدون وعده خارج از اختیار.","pages":"۱۳۹–۱۴۰"},{"id":"relationship","title":"روشن‌کردن رابطه رهبری","question":"تعریف نقش مدیر با انتظار و تجربه کارکنان کجا فاصله دارد؟","examples":"گفت‌وگوی نقش با استفاده از یک موقعیت واقعی و مقایسه برداشت‌های دو طرف.","pages":"۱۱۴–۱۱۶، ۱۳۱"}]};
